<script setup lang="ts">
import { computed, inject, ref, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import Button from 'primevue/button'; import Column from 'primevue/column'; import DataTable from 'primevue/datatable'; import Dialog from 'primevue/dialog'; import InputText from 'primevue/inputtext'; import Message from 'primevue/message'; import MultiSelect from 'primevue/multiselect'; import Select from 'primevue/select'; import Tag from 'primevue/tag';
import { useToast } from 'primevue/usetoast';
import { createProjectLabel, deleteProjectLabel, getIssueBoard, getIssues, getProjectLabels, issueStatuses, transitionIssue, updateProjectLabel } from '../../api/issues';
import type { IssueInfo, IssueLabelInfo } from '../../api/types';
import IssueCreateDialog from '../../features/issues/IssueCreateDialog.vue';
import { projectWorkspaceKey } from '../../features/projects/projectContext';
import { useI18n } from 'vue-i18n';
import { useDomainLabels } from '../../i18n/domain';

const context=inject(projectWorkspaceKey)!;const route=useRoute();const router=useRouter();const toast=useToast();
const{t,locale}=useI18n();const{issueStatusLabel,priorityLabel,issueTypeOptions,issueStatusOptions,priorityOptions}=useDomainLabels();
const issues=ref<IssueInfo[]>([]),labels=ref<IssueLabelInfo[]>([]);const total=ref(0),truncated=ref(false),loading=ref(false),moving=ref<string|null>(null);const error=ref(''),createVisible=ref(false),labelsVisible=ref(false);
const search=ref(''),type=ref<string|null>(null),status=ref<string|null>(null),priority=ref<string|null>(null),assignee=ref<string|null>(null),selectedLabels=ref<string[]>([]),view=ref<'list'|'board'>('list'),page=ref(1),pageSize=ref(20);
const newLabelName=ref(''),newLabelColor=ref('#2563EB');const labelDrafts=ref<Record<string,{name:string;color:string}>>({});
const canCreate=computed(()=>context.project.value.status==='Active'&&context.project.value.currentUserRole!=='Viewer');const canManageLabels=computed(()=>context.project.value.status==='Active'&&['Owner','Manager'].includes(context.project.value.currentUserRole));
const assigneeOptions=computed(()=>context.members.value.map(item=>({label:item.email,value:item.userId})));
const columns=computed(()=>issueStatuses.map(name=>({name,items:issues.value.filter(item=>item.status===name)})));
function fromQuery(){search.value=String(route.query.search??'');type.value=route.query.type?String(route.query.type):null;status.value=route.query.status?String(route.query.status):null;priority.value=route.query.priority?String(route.query.priority):null;assignee.value=route.query.assigneeUserId?String(route.query.assigneeUserId):null;selectedLabels.value=typeof route.query.labels==='string'?route.query.labels.split(',').filter(Boolean):[];view.value=route.query.view==='board'?'board':'list';page.value=Math.max(1,Number(route.query.page)||1);pageSize.value=[10,20,50,100].includes(Number(route.query.pageSize))?Number(route.query.pageSize):20;}
function filters(){return{search:search.value.trim(),type:type.value,status:status.value,priority:priority.value,assigneeUserId:assignee.value,labels:selectedLabels.value.join(',')}}
async function load(){loading.value=true;error.value='';try{if(!labels.value.length){labels.value=(await getProjectLabels(context.project.value.id))??[];syncDrafts();}if(view.value==='board'){const result=await getIssueBoard(context.project.value.id,filters());issues.value=result?.items??[];total.value=result?.total??0;truncated.value=result?.isTruncated??false;}else{const result=await getIssues(context.project.value.id,{...filters(),page:page.value,pageSize:pageSize.value});issues.value=result?.items??[];total.value=result?.totalCount??0;truncated.value=false;}}catch(cause){error.value=cause instanceof Error?cause.message:t('issues.loadFailed');}finally{loading.value=false;}}
function query(){return Object.fromEntries(Object.entries({...filters(),view:view.value==='board'?'board':undefined,page:view.value==='list'&&page.value!==1?String(page.value):undefined,pageSize:view.value==='list'&&pageSize.value!==20?String(pageSize.value):undefined}).filter(([,value])=>value!==undefined&&value!==null&&value!==''));}
async function apply(){page.value=1;await router.push({name:'project-issues',query:query()});}async function switchView(next:'list'|'board'){view.value=next;page.value=1;await router.push({name:'project-issues',query:query()});}
function changePage(event:{page:number;rows:number}){page.value=event.page+1;pageSize.value=event.rows;void router.push({name:'project-issues',query:query()});}function openIssue(issue:IssueInfo){void router.push({name:'project-issue-detail',params:{projectId:context.project.value.id,issueId:issue.id},query:{from:route.fullPath}});}function created(issue:IssueInfo){openIssue(issue);}
async function move(issue:IssueInfo,next:string){if(!issue.allowedTransitions.includes(next as never))return;moving.value=issue.id;try{await transitionIssue(context.project.value.id,issue.id,next);await load();}catch(cause){toast.add({severity:'error',detail:cause instanceof Error?cause.message:t('issues.transitionFailed'),life:3500});await load();}finally{moving.value=null;}}
function drop(event:DragEvent,next:string){const id=event.dataTransfer?.getData('text/issue-id');const issue=issues.value.find(item=>item.id===id);if(issue)void move(issue,next);}
function syncDrafts(){labelDrafts.value=Object.fromEntries(labels.value.map(item=>[item.id,{name:item.name,color:item.color}]))}
async function refreshLabels(){labels.value=(await getProjectLabels(context.project.value.id))??[];syncDrafts();await load();}
async function addLabel(){if(!newLabelName.value.trim())return;try{await createProjectLabel(context.project.value.id,newLabelName.value,newLabelColor.value);newLabelName.value='';await refreshLabels();}catch(cause){notify(cause);}}
async function saveLabel(item:IssueLabelInfo){const draft=labelDrafts.value[item.id];try{await updateProjectLabel(context.project.value.id,item.id,draft.name,draft.color);await refreshLabels();}catch(cause){notify(cause);}}
async function removeLabel(item:IssueLabelInfo){try{await deleteProjectLabel(context.project.value.id,item.id);selectedLabels.value=selectedLabels.value.filter(id=>id!==item.id);await refreshLabels();}catch(cause){notify(cause);}}
function notify(cause:unknown){toast.add({severity:'error',detail:cause instanceof Error?cause.message:t('common.error'),life:3500});}
watch(()=>route.query,()=>{fromQuery();void load();},{immediate:true,deep:true});
</script>
<template><section class="workspace-panel"><header class="section-header"><div><h2>{{t('issues.title')}}</h2><p>{{t('issues.subtitle')}}</p></div><div class="header-actions"><Button v-if="canManageLabels" :label="t('issues.labels')" icon="pi pi-tags" severity="secondary" @click="labelsVisible=true"/><Button v-if="canCreate" :label="t('issues.create')" icon="pi pi-plus" @click="createVisible=true"/></div></header><Message v-if="error" severity="error">{{error}}</Message><div class="view-switch"><Button :label="t('issues.list')" icon="pi pi-list" :severity="view==='list'?undefined:'secondary'" @click="switchView('list')"/><Button :label="t('issues.board')" icon="pi pi-th-large" :severity="view==='board'?undefined:'secondary'" @click="switchView('board')"/></div><div class="issue-filters"><InputText v-model="search" :placeholder="t('issues.searchPlaceholder')" @keyup.enter="apply"/><Select v-model="type" :options="issueTypeOptions" option-label="label" option-value="value" show-clear :placeholder="t('issues.type')"/><Select v-model="status" :options="issueStatusOptions" option-label="label" option-value="value" show-clear :placeholder="t('issues.status')"/><Select v-model="priority" :options="priorityOptions" option-label="label" option-value="value" show-clear :placeholder="t('issues.priority')"/><Select v-model="assignee" :options="assigneeOptions" option-label="label" option-value="value" show-clear :placeholder="t('issues.assignee')"/><MultiSelect v-model="selectedLabels" :options="labels" option-label="name" option-value="id" :placeholder="t('issues.labels')" display="chip"/><Button :label="t('issues.apply')" severity="secondary" @click="apply"/></div><DataTable v-if="view==='list'" :value="issues" :loading="loading" data-key="id" lazy paginator :rows="pageSize" :first="(page-1)*pageSize" :total-records="total" :rows-per-page-options="[10,20,50,100]" @page="changePage" @row-click="openIssue($event.data)"><template #empty>{{t('issues.empty')}}</template><Column field="title" :header="t('issues.titleField')"/><Column :header="t('issues.priority')"><template #body="{data}">{{priorityLabel(data.priority)}}</template></Column><Column :header="t('issues.labels')"><template #body="{data}"><span class="label-row"><span v-for="label in data.labels" :key="label.id" class="issue-label" :style="{borderColor:label.color}">{{label.name}}</span></span></template></Column><Column :header="t('issues.status')"><template #body="{data}"><Tag :value="issueStatusLabel(data.status)"/></template></Column><Column field="assigneeEmail" :header="t('issues.assignee')"><template #body="{data}">{{data.assigneeEmail||t('common.unassigned')}}</template></Column></DataTable><template v-else><Message v-if="truncated" severity="warn">{{t('issues.showing',{shown:issues.length,total})}}</Message><div class="kanban-board" :aria-busy="loading"><section v-for="column in columns" :key="column.name" class="kanban-column" @dragover.prevent @drop="drop($event,column.name)"><header><span>{{issueStatusLabel(column.name)}}</span><Tag :value="String(column.items.length)" severity="secondary"/></header><article v-for="item in column.items" :key="item.id" class="kanban-card" :class="{moving:moving===item.id}" draggable="true" tabindex="0" @dragstart="$event.dataTransfer?.setData('text/issue-id',item.id)" @dblclick="openIssue(item)"><button class="card-title" @click="openIssue(item)">{{item.title}}</button><small>{{priorityLabel(item.priority)}} · {{item.assigneeEmail||t('common.unassigned')}}</small><small v-if="item.dueDate" :class="{overdue:new Date(item.dueDate)<new Date()&&item.status!=='Done'}">{{t('issues.due',{date:new Date(item.dueDate).toLocaleDateString(locale)})}}</small><div class="label-row"><span v-for="label in item.labels" :key="label.id" class="issue-label" :style="{borderColor:label.color}">{{label.name}}</span></div><Select v-if="item.allowedTransitions.length" :options="item.allowedTransitions.map(value=>({value,label:issueStatusLabel(value)}))" option-label="label" option-value="value" :placeholder="t('issues.moveTo')" size="small" :disabled="moving===item.id" @change="move(item,$event.value)"/></article><p v-if="!column.items.length" class="column-empty">{{t('issues.noIssues')}}</p></section></div></template><IssueCreateDialog v-model:visible="createVisible" :labels="labels" @created="created"/><Dialog v-model:visible="labelsVisible" modal :header="t('issues.manageLabels')" :style="{width:'min(44rem,94vw)'}"><div class="label-create"><InputText v-model="newLabelName" :placeholder="t('issues.newLabel')"/><input v-model="newLabelColor" type="color" :aria-label="t('issues.labelColor')"/><Button :label="t('common.add')" @click="addLabel"/></div><div class="label-editor"><div v-for="item in labels" :key="item.id" class="label-edit-row"><InputText v-model="labelDrafts[item.id].name"/><input v-model="labelDrafts[item.id].color" type="color" :aria-label="`${item.name} ${t('issues.labelColor')}`"/><Button :label="t('common.save')" size="small" @click="saveLabel(item)"/><Button icon="pi pi-trash" severity="danger" size="small" :aria-label="t('issues.deleteLabel')" @click="removeLabel(item)"/></div><p v-if="!labels.length">{{t('issues.noLabels')}}</p></div></Dialog></section></template>
<style scoped>.workspace-panel{min-width:0;container-type:inline-size}.section-header,.header-actions,.view-switch,.label-row,.label-create,.label-edit-row{display:flex;align-items:center;gap:.6rem}.section-header{justify-content:space-between;align-items:flex-start}.section-header h2,.section-header p{margin:.2rem 0}.view-switch{margin-top:1rem}.issue-filters{display:grid;grid-template-columns:minmax(12rem,2fr) repeat(5,minmax(0,1fr)) auto;gap:.6rem;margin:1rem 0}.issue-filters>*{min-width:0;max-width:100%}.kanban-board{display:grid;width:100%;max-width:100%;min-width:0;grid-template-columns:repeat(5,minmax(17rem,1fr));gap:.8rem;overflow-x:auto;overscroll-behavior-inline:contain;padding-bottom:.5rem}.kanban-column{min-height:24rem;border:1px solid var(--surface-border);border-radius:var(--content-border-radius);background:var(--surface-ground);padding:.7rem}.kanban-column>header{display:flex;justify-content:space-between;font-weight:700;margin-bottom:.7rem}.kanban-card{display:grid;gap:.55rem;border:1px solid var(--surface-border);border-radius:var(--content-border-radius);background:var(--surface-card);padding:.8rem;margin-bottom:.65rem;box-shadow:0 4px 12px rgb(15 23 42/5%)}.kanban-card.moving{opacity:.55}.card-title{border:0;background:transparent;color:inherit;font:inherit;font-weight:700;text-align:left;padding:0;cursor:pointer}.kanban-card small,.column-empty{color:var(--text-color-secondary)}.overdue{color:var(--p-red-500)!important}.issue-label{border:1px solid;border-radius:999px;padding:.12rem .45rem;font-size:.75rem}.label-create{margin-bottom:1rem}.label-editor{display:grid;gap:.6rem}.label-edit-row>*:first-child{flex:1}@container(max-width:70rem){.issue-filters{grid-template-columns:repeat(3,minmax(0,1fr))}.issue-filters>*:first-child{grid-column:span 2}}@container(max-width:44rem){.issue-filters{grid-template-columns:repeat(2,minmax(0,1fr))}.issue-filters>*:first-child{grid-column:1/-1}}@container(max-width:28rem){.issue-filters{grid-template-columns:1fr}.issue-filters>*:first-child{grid-column:auto}.section-header{display:grid}.header-actions{flex-wrap:wrap}}</style>
